Let psm := PML.ps_set_win ps mw.
Let wptr := fst (PSA.wincells mw).
Let wend := snd (PSA.wincells mw).
Let bcap := PML.ps_bcap ps.
Let k0 := bcap / 2.
Let bptr := PML.ps_bptr ps.
