Definition E0 : env :=
  Env (reg_ev R (fun v => Z_to_bv 64 (nth (v - 32) [wptr; wend; B; k0; size0; bptr; sb; slen; scap; level; PML.ps_st ps; PML.ps_sst ps; PML.ps_nst ps; 1; done; line0; pos0; V] 0)))
