Lemma CRED_BLK : forall i j E1 E2 cr1, CH2.den E2 (nth j G.BLS []) = CH2.den E1 (nth i G.BLS []) -> Cred i E1 cr1 -> Cred j E2 cr1.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10!1,N!2+^?+^Q+^Q$i;R+^U$j;R+^U$E1;R+eO$E2;R+eO$cr1;R'f8$_H;R!3+O!1+>!2+^?+2+2!2'f9#2!4'1'^O#4'^00!2'f9#3!4'1'^O#5'^00$H;R!3'f:#6#4#2#1").
Qed.

