Lemma FRZ : forall E', env_agree GT.NF E0 E' ->
  uv E' (EVar 2) = sp /\ uv E' Pb = P /\ uv E' Eb = E /\ uv E' (EVar 41) = level /\ uv E' (EVar 43) = PML.ps_sst ps /\ uv E' (EVar 44) = PML.ps_nst ps /\ uv E' (EVar 46) = done /\
